const { execSync } = require('child_process');
const action = (params.action || 'list').toLowerCase();
function safeExec(cmd, timeoutMs = 5000) {
  try { return execSync(cmd, { encoding: 'utf8', timeout: timeoutMs }); } catch (e) { return ''; }
}
if (action === 'list') {
  const pattern = params.pattern ? new RegExp(params.pattern, 'i') : null;
  const limit = Number(params.limit ?? 40);
  const raw = safeExec('ps -axo pid,user,%cpu,%mem,command');
  const lines = raw.split('\n').filter(l => l.trim());
  const header = lines.shift();
  const rows = lines.filter(l => !pattern || pattern.test(l)).slice(0, limit).map(l => l.trim());
  return { header, count: rows.length, processes: rows };
}
if (action === 'port') {
  const port = params.port;
  if (!port) throw new Error('params.port required');
  if (process.platform === 'win32') return { raw: safeExec(`netstat -ano | findstr :${port}`) };
  return { raw: safeExec(`lsof -nP -iTCP:${port} -sTCP:LISTEN 2>/dev/null || netstat -anv -p tcp | grep ${port}`) };
}
throw new Error('Unknown action: ' + action);
